import csv
import json
import os
from datetime import datetime, date
from pathlib import Path

PROJECT_DIR = Path(os.environ.get("BIOTECH_PROJECT_DIR", Path(__file__).parent))
DATA_DIR = PROJECT_DIR / "data"
UNIVERSE_FILE = DATA_DIR / "universe" / "biotech_universe_v1.csv"
TRIAL_MAP_FILE = DATA_DIR / "trial_mapping.csv"
AACT_DIR = DATA_DIR / "aact_snapshots"


def load_universe():
    if not UNIVERSE_FILE.exists():
        return []
    with open(UNIVERSE_FILE, newline="", encoding="utf-8") as f:
        return list(csv.DictReader(f))

def load_trial_map():
    if not TRIAL_MAP_FILE.exists():
        return {}
    mapping = {}
    with open(TRIAL_MAP_FILE, newline="", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            ticker = row.get("ticker", "").upper()
            if ticker:
                mapping.setdefault(ticker, []).append(row)
    return mapping


def load_aact_studies():
    if not AACT_DIR.is_dir():
        return {}
    subdirs = sorted(p for p in AACT_DIR.iterdir() if p.is_dir())
    if not subdirs:
        return {}
    studies_file = subdirs[-1] / "studies.csv"
    if not studies_file.exists():
        return {}
    out = {}
    with open(studies_file, newline="", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            nct = (row.get("nct_id") or "").strip()
            if nct:
                out[nct] = row
    return out


def load_aact_sponsors():
    if not AACT_DIR.is_dir():
        return {}
    subdirs = sorted(p for p in AACT_DIR.iterdir() if p.is_dir())
    if not subdirs:
        return {}
    sponsors_file = subdirs[-1] / "sponsors.csv"
    if not sponsors_file.exists():
        return {}
    out = {}
    with open(sponsors_file, newline="", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            nct = (row.get("nct_id") or "").strip()
            name = (row.get("name") or "").strip()
            if nct and name:
                out.setdefault(nct, []).append(name)
    return out


universe = load_universe()
trial_map = load_trial_map()
aact_studies = load_aact_studies()
aact_sponsors = load_aact_sponsors()

today = date(2026, 6, 21)
cutoff = date(2026, 9, 19)  # 90 days out

print(f"Universe size: {len(universe)}")
print(f"Tickers with trials: {len(trial_map)}")
print(f"AACT studies loaded: {len(aact_studies)}")
print(f"Today: {today}, 90-day cutoff: {cutoff}")
print("---")

upcoming = []

for company in universe:
    ticker = company.get("ticker", "").upper()
    name = company.get("name", "")
    trials = trial_map.get(ticker, [])
    if not trials:
        continue
    for t in trials:
        nct = t.get("nct_id", "")
        study = aact_studies.get(nct, {})
        pcd_str = study.get("primary_completion_date", "")
        status = study.get("overall_status", "")
        phase = study.get("phase", "Unknown")
        sponsors = aact_sponsors.get(nct, [])
        sponsor_at_map = t.get("sponsor_name_at_map_time", "")

        if pcd_str and len(pcd_str) >= 10:
            try:
                pcd_date = datetime.strptime(pcd_str[:10], "%Y-%m-%d").date()
                if today <= pcd_date <= cutoff:
                    days_away = (pcd_date - today).days
                    upcoming.append({
                        "ticker": ticker,
                        "name": name,
                        "nct_id": nct,
                        "phase": phase,
                        "status": status,
                        "pcd": pcd_str[:10],
                        "days_away": days_away,
                        "sponsors": sponsors,
                        "sponsor_at_map": sponsor_at_map,
                        "company_detail": {k: company.get(k, "") for k in ["ticker", "name", "sector", "market_cap", "stage"]}
                    })
            except ValueError:
                pass

# Sort by days away
upcoming.sort(key=lambda x: x["days_away"])

print(f"\nUpcoming catalysts (next 90 days): {len(upcoming)}")
print(json.dumps(upcoming, indent=2))

